import unittest

from solucao import campo_do_meio


class TestFatiarOTexto(unittest.TestCase):
    def test_pega_o_campo_do_meio(self):
        """campo_do_meio devolve o pedaco entre a primeira e a segunda marca"""
        self.assertEqual(campo_do_meio("PEDIDO-4321-URGENTE", "-"), "4321")

    def test_pega_um_caractere_so(self):
        """campo_do_meio devolve o campo mesmo quando ele tem um caractere"""
        self.assertEqual(campo_do_meio("A-1-B", "-"), "1")

    def test_aceita_outra_marca(self):
        """campo_do_meio funciona com qualquer marca pedida"""
        self.assertEqual(campo_do_meio("12/34/56", "/"), "34")

    def test_uma_marca_so_devolve_o_resto(self):
        """campo_do_meio devolve tudo depois da marca quando so ha uma"""
        self.assertEqual(campo_do_meio("abc-def", "-"), "def")

